      .filter((key) => score.profile[key] !== undefined)
      .map((key) => [key, score.profile[key].trim()]));
    const payload = { companyName: lead.companyName.trim(), contactName: trimmed(score.contactName ?? lead.contactName), phone: trimmed(score.phone ?? lead.phone), email: trimmed(score.email ?? lead.email), source: lead.source, sourceUrl: lead.sourceUrl, searchKeyword: trimmed(lead.searchKeyword), aiScore: score.aiScore, profile: normalizedProfile, sourceModelVersion: entry.sourceModelVersion.trim(), extractorVersion: entry.extractorVersion.trim(), sourceSystem: lead.sourceSystem.trim(), externalLeadId: lead.externalLeadId.trim() };
    Object.keys(payload).forEach((key) => payload[key] === undefined && delete payload[key]);
    items.push({ idempotencyKey: lead.idempotencyKey, payloadHash: await hash(payload), ...payload });
  }
  return { items };
}
